import React,{useState} from 'react';import{createRoot}from'react-dom/client';import TableViewport from'../../app/table-viewport';import'../../app/readability.css';
function Preview(){const[status,setStatus]=useState('No action taken');return <main id="portal-workspace" data-page="Payroll" style={{padding:16,color:'#17324d',background:'#fff'}}><h1>Synthetic comparison · no real records</h1><TableViewport label="Synthetic payroll comparison" className="table-wrap"><table style={{minWidth:1200}}><thead><tr>{Array.from({length:12},(_,i)=><th key={i}>Category {i+1}</th>)}<th>Action</th></tr></thead><tbody><tr>{Array.from({length:12},(_,i)=><td key={i}>Synthetic value {i+1}</td>)}<td><button onClick={()=>setStatus('Synthetic full record opened')}>Open full record</button></td></tr></tbody></table></TableViewport><p role="status">{status}</p></main>;}createRoot(document.getElementById('root')!).render(<Preview/>);
